<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Asset Turnover Form · {{ $transfer->reference_no }}</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{font:14px Arial,sans-serif;color:#17243a}.sheet{max-width:850px;margin:30px auto;padding:42px;border:1px solid #d9dee7}.muted{color:#68758a}.signature{height:75px;border-bottom:1px solid #667085;margin-top:28px}@media print{.no-print{display:none!important}.sheet{border:0;margin:0;max-width:none;padding:0}}</style></head><body><main class="sheet"><header class="d-flex justify-content-between border-bottom pb-3 mb-4"><div><h4 class="mb-1">{{ $organizationName }}</h4><div class="muted">IT Asset Accountability / Turnover</div></div><div class="text-end"><strong>{{ $transfer->reference_no }}</strong><div class="muted">{{ $transfer->created_at?->format(config('app.date_format','d M Y')) }}</div></div></header><h5>Asset being transferred</h5><table class="table table-bordered"><tbody><tr><th style="width:30%">Asset Tag</th><td>{{ $transfer->asset?->asset_tag }}</td></tr><tr><th>Equipment</th><td>{{ $transfer->asset?->name }}</td></tr><tr><th>Serial Number</th><td>{{ $transfer->asset?->serial_number ?? '—' }}</td></tr><tr><th>Transfer Type</th><td>{{ ucfirst($transfer->transfer_type ?? 'permanent') }}</td></tr><tr><th>From Custodian</th><td>{{ $transfer->fromEmployee?->full_name }} — {{ $transfer->fromEmployee?->department?->name ?? '—' }}</td></tr><tr><th>To Custodian</th><td>{{ $transfer->toEmployee?->full_name }} — {{ $transfer->toDepartment?->name ?? $transfer->toEmployee?->department?->name ?? '—' }}</td></tr><tr><th>Destination Location</th><td>{{ $transfer->toLocation?->name ?? $transfer->asset?->location?->name ?? '—' }}</td></tr><tr><th>Reason</th><td>{{ $transfer->reason }}</td></tr><tr><th>Status</th><td>{{ ucfirst($transfer->status) }}</td></tr></tbody></table><p class="mt-4">The undersigned acknowledge the transfer and turnover of custody of the equipment identified above, subject to applicable property accountability procedures.</p><div class="row mt-5"><div class="col-6"><div class="signature"></div><strong>{{ $transfer->fromEmployee?->full_name }}</strong><div class="muted">Outgoing custodian</div></div><div class="col-6"><div class="signature"></div><strong>{{ $transfer->toEmployee?->full_name }}</strong><div class="muted">Incoming custodian</div></div></div><div class="row mt-4"><div class="col-6"><div class="signature"></div><strong>{{ $transfer->approver?->name ?? ' ' }}</strong><div class="muted">Approving authority</div></div><div class="col-6"><div class="signature"></div><strong>{{ $transfer->receiver?->name ?? ' ' }}</strong><div class="muted">Receiving / property representative</div></div></div><div class="mt-5 pt-3 border-top muted small">Generated by the IT Inventory Management System. This form documents the recorded turnover and does not replace any legally prescribed property form.</div><div class="mt-4 no-print"><button class="btn btn-primary" onclick="window.print()">Print / Save as PDF</button> <button class="btn btn-light border" onclick="history.back()">Back</button></div></main></body></html>
